          y: ship.y + ship.h,
          vx: (Math.random() - 0.5) * 0.5,
          vy: 0.5 + Math.random() * 0.5,
          life: 300,
          size: Math.random() * 2 + 1,
          hue: Math.random() * 360,
        });
      }
    }
    // update particles
    particles.forEach(p => {
      p.x += p.vx;
      p.y += p.vy;
      p.life -= dt;
    });
    // remove dead particles
    while (particles.length && particles[0].life <= 0) particles.shift();
    // stars
    stars.forEach(s => {
      s.y += s.speed;
      if (s.y > ch) { s.y = 0; s.x = Math.random() * cw; }
    });
    // asteroids
    const now = performance.now();
    if (now - lastSpawn > spawnInterval) { spawnAsteroid(); lastSpawn = now; }
    asteroids.forEach(a => a.y += a.speed);
    asteroids = asteroids.filter(a => a.y < ch);
    // collision
    if (asteroids.some(a => rectIntersect(ship, a))) gameOver = true;

